(6524891, 970670, 36628, '<td valign="top">Took three times looking at this to see those were actually hands! This is a really cool image.</td>', 'Took three times looking at this to see those were actually hands! This is a really cool image.', '2011-09-02 13:17:46.000000', NULL, 1),
(6524896, 969472, 115307, '<td valign="top">Because of the extreme closeup, this image almost looks 3D! It feels like that nose is sticking right out of the screen!</td>', 'Because of the extreme closeup, this image almost looks 3D! It feels like that nose is sticking right out of the screen!', '2011-09-02 13:21:44.000000', NULL, 1),
(6524906, 970670, 115307, '<td valign="top">At first I thought this was weird, then I realized that this entire thing was made out of hands and I realized just how awesome and fantastic this is. What hard work! The fist pupils just put the icing on the cake. 9</td>', 'At first I thought this was weird, then I realized that this entire thing was made out of hands and I realized just how awesome and fantastic this is. What hard work! The fist pupils just put the icing on the cake. 9', '2011-09-02 13:24:48.000000', NULL, 1),
(6524907, 970591, 69324, '<td valign="top">Really nice work, I hope you score well.</td>', 'Really nice work, I hope you score well.', '2011-09-02 13:24:56.000000', NULL, 1),
(6524919, 970670, 74559, '<td valign="top">Totally bizarre. That must have taken a long time. I love it!</td>', 'Totally bizarre. That must have taken a long time. I love it!', '2011-09-02 13:28:28.000000', NULL, 1),
(6524925, 970674, 74559, '<td valign="top">Wowsers! I''ll take one of those, please :-) Beautiful execution of a very cool idea!</td>', 'Wowsers! I''ll take one of those, please :-) Beautiful execution of a very cool idea!', '2011-09-02 13:32:04.000000', NULL, 1),
(6524926, 970230, 135278, '<td valign="top">Almost kind of a strange optical illusion with this one, atleast for me... When I look at the guy on the bull, the "ghosted" image almost fades away.  Very cool.</td>', 'Almost kind of a strange optical illusion with this one, atleast for me... When I look at the guy on the bull, the "ghosted" image almost fades away.  Very cool.', '2011-09-02 13:33:58.000000', NULL, 1),
(6524934, 970670, 49683, '<td valign="top">Awesome</td>', 'Awesome', '2011-09-02 13:55:02.000000', NULL, 1),
(6525067, 970628, 103818, '<td valign="top">I was immediately drawn to this photo. It deserves to be on a billboard somewhere. Definitely a 10 and the best I''ve seen thus far. Good luck hope you ribbon.</td>', 'I was immediately drawn to this photo. It deserves to be on a billboard somewhere. Definitely a 10 and the best I''ve seen thus far. Good luck hope you ribbon.', '2011-09-02 15:22:37.000000', NULL, 1),
