(6525096, 970670, 124815, '<td valign="top">Heck, why these exercises end up almost all the time looking ugly? Lot of work here but ....<br/>No mark</td>', 'Heck, why these exercises end up almost all the time looking ugly? Lot of work here but ....No mark', '2011-09-02 15:42:10.000000', NULL, 1),
(6525102, 970587, 124815, '<td valign="top">An exercise done over and over again - well applied here. I certainly recognize the good work even if it''s not exacly my cup of tea.</td>', 'An exercise done over and over again - well applied here. I certainly recognize the good work even if it''s not exacly my cup of tea.', '2011-09-02 15:44:33.000000', NULL, 1),
(6525111, 970591, 124815, '<td valign="top">Totally haunting in the best possible sense. The look on the eyes took me back to the promises of childhood. It''s also a picture after a war. 10, of course</td>', 'Totally haunting in the best possible sense. The look on the eyes took me back to the promises of childhood. It''s also a picture after a war. 10, of course', '2011-09-02 15:47:11.000000', NULL, 1),
