(6533523, 970709, 125275, '<td valign="top">This is an interesting take on "expert editing." I really didn''t think of it this way, but this is a really cool series!</td>', 'This is an interesting take on "expert editing." I really didn''t think of it this way, but this is a really cool series!', '2011-09-08 17:30:37.000000', NULL, 1),
(6533526, 970094, 125275, '<td valign="top">Pretty funny facial expressions! And you did a nice job of lining up the eyes. The top of the ''mask'' is a bit soft, but that''s not a big deal. Also a good use of complementary colors.</td>', 'Pretty funny facial expressions! And you did a nice job of lining up the eyes. The top of the ''mask'' is a bit soft, but that''s not a big deal. Also a good use of complementary colors.', '2011-09-08 17:32:05.000000', NULL, 1),
