(6533530, 970705, 125275, '<td valign="top">Nice and clear. A good job of noise reduction to soften the skin and the eyes are nice a bright.</td>', 'Nice and clear. A good job of noise reduction to soften the skin and the eyes are nice a bright.', '2011-09-08 17:33:17.000000', NULL, 1),
(6533531, 970611, 125275, '<td valign="top">A little dark but I like the tones and posing.</td>', 'A little dark but I like the tones and posing.', '2011-09-08 17:33:50.000000', NULL, 1),
