(6534320, 970670, 77729, '<td valign="top">How can anybody score this below an 8? Very impressive - 10 for me, contgrats on the well deserved ribbon!<br/><br/><i>Message edited by author 2011-09-09 00:23:26.</i></td>', 'How can anybody score this below an 8? Very impressive - 10 for me, contgrats on the well deserved ribbon!', '2011-09-09 01:22:52.000000', '2011-09-09 01:23:26.000000', 0),
(6534323, 970591, 100831, '<td valign="top">It''s the happily part that works for me. Go Ben.</td>', 'It''s the happily part that works for me. Go Ben.', '2011-09-09 01:23:26.000000', NULL, 0),
(6534335, 970670, 75713, '<td valign="top">I stand in awe ... genius work deserving of recognition in the finest of Art galleries.</td>', 'I stand in awe ... genius work deserving of recognition in the finest of Art galleries.', '2011-09-09 01:26:21.000000', NULL, 0),
(6534368, 969517, 123348, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by alanfreed:</b></div><hr/><i> Doesn''t really strike me as much of a male portrait. </i></td></tr></table> <br/>Your comment made me laugh out loud:) Thank you...</td>', 'Originally posted by alanfreed: Doesn''t really strike me as much of a male portrait.  Your comment made me laugh out loud:) Thank you...', '2011-09-09 01:31:58.000000', NULL, 0),
(6534384, 970670, 114285, '<td valign="top">Wow Christophe, I did''nt look hard enough at this, the first time around and never realised it was your hands in this photo, shame on me. Deserved of a ribbon, due to the hours you must''ve spent producing this master piece, congrats on the 1X as well.</td>', 'Wow Christophe, I did''nt look hard enough at this, the first time around and never realised it was your hands in this photo, shame on me. Deserved of a ribbon, due to the hours you must''ve spent producing this master piece, congrats on the 1X as well.', '2011-09-09 01:36:36.000000', NULL, 0),
(6534390, 970628, 27108, '<td valign="top">Congrats on well deserved Blue Ribbon!! :)   <br/> <br/>"I voted 10 on this one!, wasnt wrong!"</td>', 'Congrats on well deserved Blue Ribbon!! :)    "I voted 10 on this one!, wasnt wrong!"', '2011-09-09 01:38:24.000000', NULL, 0),
(6534392, 970670, 27108, '<td valign="top">Congrats on well deserved Brown Ribbon!! :)   <br/> <br/>"I voted 10 on this one!, wasnt wrong!"</td>', 'Congrats on well deserved Brown Ribbon!! :)    "I voted 10 on this one!, wasnt wrong!"', '2011-09-09 01:39:10.000000', NULL, 0),
(6534396, 970094, 27108, '<td valign="top">Congrats on well deserved yellow/gold ribbon!<br/> <br/>I voted a 9 on this one!.. (just because of the blurriness around "the mask"... not the trail from your head.. but around the edge of mask, specially at top left).</td>', 'Congrats on well deserved yellow/gold ribbon! I voted a 9 on this one!.. (just because of the blurriness around "the mask"... not the trail from your head.. but around the edge of mask, specially at top left).', '2011-09-09 01:41:45.000000', NULL, 0),
(6534400, 970709, 27108, '<td valign="top">This image should be a bit higher, but hey!.. mine ended at 27! in the female challenge! :P</td>', 'This image should be a bit higher, but hey!.. mine ended at 27! in the female challenge! :P', '2011-09-09 01:42:44.000000', NULL, 0),
(6534401, 970587, 83313, '<td valign="top">Hey, a new PB! Congrats!</td>', 'Hey, a new PB! Congrats!', '2011-09-09 01:42:50.000000', NULL, 0),
(6534407, 969517, 83313, '<td valign="top">4.43?!! You just get no respect...</td>', '4.43?!! You just get no respect...', '2011-09-09 01:45:13.000000', NULL, 0),
(6534410, 970628, 86447, '<td valign="top">Yup.   Knew this would not be RED, but BLUE the second I took it all in. <br/> <br/>WELL DONE!    Congrats you your vision, your modeling, and your photography.<br/></td>', 'Yup.   Knew this would not be RED, but BLUE the second I took it all in.  WELL DONE!    Congrats you your vision, your modeling, and your photography.', '2011-09-09 01:46:19.000000', NULL, 0),
